def choose_move(observation):
    wx, wy = observation.get('grid_width', 0), observation.get('grid_height', 0)
    px, py = observation.get('self_position', [0,0])
    resources = observation.get('resources', [])
    obstacles = set(tuple(obs) for obs in observation.get('obstacles', []))
    opponent = observation.get('opponent_position', [0,0])
    score_self = observation.get('scores', [0])[0]
    score_opp = observation.get('scores', [0])[1]

    def dist(a,b): return abs(a[0]-b[0])+abs(a[1]-b[1])
    target = None
    if resources:
        target = min(resources, key=lambda r: dist((px,py),(r[0],r[1])))
    else:
        target = opponent

    dx = dy = 0
    if target:
        dx = (target[0]-px)
        dy = (target[1]-py)
        dx = (dx>0)-(dx<0)
        dy = (dy>0)-(dy<0)

    for move in [(dx,dy),(dx,0),(0,dy),(0,0)]:
        nx, ny = px+move[0], py+move[1]
        if 0<=nx<wx and 0<=ny<wy and (nx,ny) not in obstacles:
            return list(move)
    return [0,0]
